double calculate_entropy(const std::string& data) {
    std::map<char, int> freq;
    for (char c : data) { freq[c]++; }
    double entropy = 0.0;
    double len = (double)data.length();
    for (auto const& [key, val] : freq) {
        double p = (double)val / len;
        entropy -= p * std::log2(p);
    }
    return entropy;
}

