namespace QuantumErrorCorrection {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Arrays;

    /// # Summary
    /// Implements Steane 7-qubit error correction code (CSS code)
    /// Can correct any single-bit error (bit-flip or phase-flip)

    operation SteaneEncode(data : Qubit) : Qubit[] {
        // Allocate ancilla qubits
        use ancillas = Qubit[6];
        let qubits = [data] + ancillas;

        // Apply encoding circuit for [[7,1,3]] Steane code
        // Generator matrix encodes logical |0⟩ -> |0000000⟩ + |1111111⟩
        CNOT(qubits[0], qubits[1]);
        CNOT(qubits[0], qubits[2]);
        CNOT(qubits[0], qubits[4]);
        CNOT(qubits[0], qubits[5]);
        CNOT(qubits[0], qubits[6]);

        H(qubits[0]);
        H(qubits[1]);
        H(qubits[2]);

        return qubits;
    }

    operation SteaneDecode(encoded : Qubit[]) : Result {
        // Syndrome measurement for bit-flip errors
        use syndromeX = Qubit[3];

        // Parity checks (stabilizer measurements)
        CNOT(encoded[0], syndromeX[0]);
        CNOT(encoded[2], syndromeX[0]);
        CNOT(encoded[4], syndromeX[0]);
        CNOT(encoded[6], syndromeX[0]);

        CNOT(encoded[1], syndromeX[1]);
        CNOT(encoded[2], syndromeX[1]);
        CNOT(encoded[5], syndromeX[1]);
        CNOT(encoded[6], syndromeX[1]);

        CNOT(encoded[3], syndromeX[2]);
        CNOT(encoded[4], syndromeX[2]);
        CNOT(encoded[5], syndromeX[2]);
        CNOT(encoded[6], syndromeX[2]);

        // Measure syndrome
        let syndromeResultX = MultiM(syndromeX);

        // Syndrome measurement for phase-flip errors
        use syndromeZ = Qubit[3];

        for i in 0..2 {
            H(syndromeZ[i]);
        }

        // Phase syndrome checks
        CZ(encoded[0], syndromeZ[0]);
        CZ(encoded[2], syndromeZ[0]);
        CZ(encoded[4], syndromeZ[0]);
        CZ(encoded[6], syndromeZ[0]);

        CZ(encoded[1], syndromeZ[1]);
        CZ(encoded[2], syndromeZ[1]);
        CZ(encoded[5], syndromeZ[1]);
        CZ(encoded[6], syndromeZ[1]);

        CZ(encoded[3], syndromeZ[2]);
        CZ(encoded[4], syndromeZ[2]);
        CZ(encoded[5], syndromeZ[2]);
        CZ(encoded[6], syndromeZ[2]);

        for i in 0..2 {
            H(syndromeZ[i]);
        }

        let syndromeResultZ = MultiM(syndromeZ);

        // Apply corrections based on syndrome
        ApplyCorrection(encoded, syndromeResultX, syndromeResultZ);

        // Decode (reverse of encoding)
        H(encoded[2]);
        H(encoded[1]);
        H(encoded[0]);

        return M(encoded[0]);
    }

    operation ApplyCorrection(qubits : Qubit[], syndromeX : Result[], syndromeZ : Result[]) : Unit {
        // Lookup table for error correction
        let errorIdx = ResultArrayAsInt(syndromeX);

        if (errorIdx != 0) {
            // Apply X correction
            X(qubits[errorIdx - 1]);
        }

        let phaseErrorIdx = ResultArrayAsInt(syndromeZ);

        if (phaseErrorIdx != 0) {
            // Apply Z correction
            Z(qubits[phaseErrorIdx - 1]);
        }
    }

    /// # Summary
    /// Bit-flip code (simple 3-qubit repetition)
    operation BitFlipCode(data : Qubit) : Qubit[] {
        use ancillas = Qubit[2];
        let qubits = [data] + ancillas;

        CNOT(qubits[0], qubits[1]);
        CNOT(qubits[0], qubits[2]);

        return qubits;
    }

    operation BitFlipCorrect(encoded : Qubit[]) : Result {
        // Measure syndrome
        use syndrome = Qubit[2];

        CNOT(encoded[0], syndrome[0]);
        CNOT(encoded[1], syndrome[0]);

        CNOT(encoded[1], syndrome[1]);
        CNOT(encoded[2], syndrome[1]);

        let s = MultiM(syndrome);

        // Majority vote correction
        if (s[0] == One and s[1] == Zero) {
            X(encoded[0]);
        } elif (s[0] == One and s[1] == One) {
            X(encoded[1]);
        } elif (s[0] == Zero and s[1] == One) {
            X(encoded[2]);
        }

        return M(encoded[0]);
    }

    @EntryPoint()
    operation RunErrorCorrection() : Unit {
        Message("🛡️ Q# Quantum Error Correction");

        // Test Steane code
        use data = Qubit();
        X(data);  // Prepare |1⟩

        let encoded = SteaneEncode(data);

        // Introduce error
        X(encoded[2]);

        let result = SteaneDecode(encoded);

        if (result == One) {
            Message("✅ Steane code: Error corrected successfully!");
        } else {
            Message("❌ Steane code: Error correction failed");
        }

        ResetAll(encoded);
    }
}

