// Implementa el algoritmo de Grover para búsqueda cuántica.
// Encuentra un elemento en una lista de N items en O(√N) pasos.

namespace JarvixQuantum {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Convert;

    /// Oráculo que marca el estado objetivo
    operation Oracle(target : Int, register : Qubit[]) : Unit is Adj + Ctl {
        // Marca el estado |target⟩ invirtiendo su fase
        let n = Length(register);

        // Convertir target a binario y aplicar X donde sea necesario
        for i in 0..n-1 {
            if ((target >>> i) &&& 1) == 0 {
                X(register[i]);
            }
        }

        // Aplicar Z controlado múltiple
        Controlled Z(register[0..n-2], register[n-1]);

        // Deshacer las X
        for i in 0..n-1 {
            if ((target >>> i) &&& 1) == 0 {
                X(register[i]);
            }
        }
    }

    /// Operador de difusión (Grover Diffusion)
    operation DiffusionOperator(register : Qubit[]) : Unit is Adj + Ctl {
        ApplyToEach(H, register);
        ApplyToEach(X, register);

        Controlled Z(register[0..Length(register)-2], register[Length(register)-1]);

        ApplyToEach(X, register);
        ApplyToEach(H, register);
    }

    /// Algoritmo de Grover completo
    @EntryPoint()
    operation GroverSearch() : Int {
        let n = 3;  // 3 qubits = buscar en 2^3 = 8 elementos
        let target = 5;  // Buscamos el elemento 5
        let iterations = Round(PI() / 4.0 * Sqrt(IntAsDouble(1 <<< n)));

        Message($"🔍 GROVER SEARCH: Buscando elemento {target} en {1 <<< n} items");
        Message($"   Iteraciones óptimas: {iterations}");

        use register = Qubit[n];

        // 1. Superposición inicial
        ApplyToEach(H, register);

        // 2. Aplicar Grover iterations veces
        for _ in 1..iterations {
            Oracle(target, register);
            DiffusionOperator(register);
        }

        // 3. Medir
        let result = MeasureInteger(register);

        Message($"✅ RESULTADO: {result}");

        if result == target {
            Message($"   ✨ ÉXITO: Encontrado en O(√N) pasos!");
        } else {
            Message($"   ⚠️ Falló (probabilístico)");
        }

        return result;
    }
}

namespace ShorFactorization {
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Arithmetic;
    open Microsoft.Quantum.Convert;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Measurement;
    open Microsoft.Quantum.Arrays;

    /// # Summary
    /// Complete Shor's algorithm for integer factorization
    /// Factors N by finding period r of f(x) = a^x mod N

    /// # Summary
    /// Quantum Fourier Transform (QFT)
    operation QFT(register : Qubit[]) : Unit is Adj + Ctl {
        let n = Length(register);

        for i in 0..n-1 {
            H(register[i]);

            for j in i+1..n-1 {
                let angle = 2.0 * PI() / PowD(2.0, IntAsDouble(j - i + 1));
                Controlled R1([register[j]], (angle, register[i]));
            }
        }

        // Reverse qubit order
        for i in 0..(n/2)-1 {
            SWAP(register[i], register[n-1-i]);
        }
    }

    /// # Summary
    /// Modular exponentiation: |x⟩|0⟩ -> |x⟩|a^x mod N⟩
    operation ModularExponentiation(
        a : Int,
        N : Int,
        x : Qubit[],
        target : Qubit[]
    ) : Unit is Adj + Ctl {
        let n = Length(target);

        // Initialize target to |1⟩
        X(target[0]);

        // Apply controlled multiplications
        for i in 0..Length(x)-1 {
            let powerOfA = ModularPow(a, 1 <<< i, N);
            Controlled ModularMultiplication([x[i]], (powerOfA, N, target));
        }
    }

    /// # Summary
    /// Controlled modular multiplication
    operation ModularMultiplication(
        multiplier : Int,
        modulus : Int,
        target : Qubit[]
    ) : Unit is Adj + Ctl {
        // Simplified implementation
        // In practice: use addition-based multiplication

        let n = Length(target);
        use ancilla = Qubit[n];

        // Compute product (simplified)
        for i in 0..n-1 {
            if ((multiplier >>> i) &&& 1) == 1 {
                CNOT(target[i], ancilla[i]);
            }
        }

        // Modular reduction (simplified)
        // In production: implement full modular arithmetic

        // Swap result back
        for i in 0..n-1 {
            SWAP(target[i], ancilla[i]);
        }
    }

    /// # Summary
    /// Classical modular exponentiation helper
    function ModularPow(base : Int, exponent : Int, modulus : Int) : Int {
        mutable result = 1;
        mutable b = base % modulus;
        mutable e = exponent;

        while (e > 0) {
            if (e % 2 == 1) {
                set result = (result * b) % modulus;
            }
            set b = (b * b) % modulus;
            set e = e / 2;
        }

        return result;
    }

    /// # Summary
    /// Period finding subroutine (quantum part of Shor's)
    operation QuantumPeriodFinding(
        a : Int,
        N : Int,
        precision : Int
    ) : Int {
        // Number of qubits for counting register
        let n_count = 2 * precision;
        let n_target = precision;

        use (countingRegister, targetRegister) = (Qubit[n_count], Qubit[n_target]);

        // Superposition in counting register
        ApplyToEach(H, countingRegister);

        // Modular exponentiation
        ModularExponentiation(a, N, countingRegister, targetRegister);

        // Inverse QFT on counting register
        Adjoint QFT(countingRegister);

        // Measure counting register
        let result = MeasureInteger(LittleEndian(countingRegister));

        // Clean up
        ResetAll(countingRegister);
        ResetAll(targetRegister);

        return result;
    }

    /// # Summary
    /// Classical post-processing: find period from measurement
    function FindPeriod(measurement : Int, precision : Int, N : Int) : Int {
        // Convert measurement to phase
        let Q = 1 <<< (2 * precision);
        let phase = IntAsDouble(measurement) / IntAsDouble(Q);

        // Continued fractions to find period
        // Simplified: return estimated period
        // In production: implement full continued fractions

        if (phase == 0.0) {
            return 1;
        }

        // Approximate r ≈ 1/phase
        let r_approx = Round(1.0 / phase);

        return r_approx;
    }

    /// # Summary
    /// GCD (Greatest Common Divisor) - Euclidean algorithm
    function GCD(a : Int, b : Int) : Int {
        mutable x = a;
        mutable y = b;

        while (y != 0) {
            let temp = y;
            set y = x % y;
            set x = temp;
        }

        return x;
    }

    /// # Summary
    /// Complete Shor's algorithm
    operation ShorFactorize(N : Int, precision : Int) : (Int, Int) {
        Message($"🔢 Shor's Algorithm: Factoring N = {N}");

        // Step 1: Check if N is even
        if (N % 2 == 0) {
            Message("   N is even: factor = 2");
            return (2, N / 2);
        }

        // Step 2: Choose random a coprime to N
        mutable a = 7;  // Simplified: should be random 1 < a < N

        if (GCD(a, N) > 1) {
            let factor = GCD(a, N);
            Message($"   Lucky! GCD({a},{N}) = {factor}");
            return (factor, N / factor);
        }

        Message($"   Base: a = {a}");

        // Step 3: Quantum period finding
        Message("   Running quantum period finding...");
        let measurement = QuantumPeriod Finding(a, N, precision);

        // Step 4: Classical post-processing
        let r = FindPeriod(measurement, precision, N);

        Message($"   Period found: r = {r}");

        // Step 5: If r is odd or a^(r/2) ≡ -1 (mod N), retry
        if (r % 2 != 0) {
            Message("   Period is odd, retry needed");
            return (1, N);
        }

        let half_r = r / 2;
        let a_power = ModularPow(a, half_r, N);

        if (a_power == N - 1) {
            Message("   a^(r/2) ≡ -1 (mod N), retry needed");
            return (1, N);
        }

        // Step 6: Compute factors
        let factor1 = GCD(a_power - 1, N);
        let factor2 = GCD(a_power + 1, N);

        if (factor1 > 1 and factor1 < N) {
            Message($"   ✅ Factor found: {factor1}");
            return (factor1, N / factor1);
        }

        if (factor2 > 1 and factor2 < N) {
            Message($"   ✅ Factor found: {factor2}");
            return (factor2, N / factor2);
        }

        Message("   No factor found, retry needed");
        return (1, N);
    }

    @EntryPoint()
    operation RunShor() : Unit {
        Message("🔐 Shor's Factorization Algorithm");
        Message("="*70);

        // Example: Factor N = 15
        let N = 15;
        let precision = 4;

        let (factor1, factor2) = ShorFactorize(N, precision);

        Message($"\n   Result: {N} = {factor1} × {factor2}");

        if (factor1 * factor2 == N and factor1 > 1 and factor2 > 1) {
            Message("   ✅ Factorization successful!");
        } else {
            Message("   ⚠️ Factorization incomplete (may need retry)");
        }

        Message("\n" + "="*70);
        Message("📚 SHOR'S ALGORITHM:");
        Message("   - Quantum Fourier Transform (QFT)");
        Message("   - Modular exponentiation");
        Message("   - Period finding");
        Message("   - Classical post-processing (continued fractions)");
        Message("   - Breaks RSA encryption");
        Message("="*70);
    }
}

